'use strict';
const H={};
const p={"configured":"yes","sensor":"yes"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 启动时处于未配置状态
Object.assign(s, ((s,p)=>({states:['unconfigured'],active:false}))(s, p));
// 配置资源并检查参数
Object.assign(s, ((s,p)=>({states:s.states.concat(p.configured==='yes'?'inactive':'unconfigured'),configured:p.configured==='yes'}))(s, p));
// 满足依赖后激活
Object.assign(s, ((s,p)=>({active:s.configured&&p.sensor==='yes',states:s.states.concat(s.configured&&p.sensor==='yes'?'active':'blocked')}))(s, p));
// 为目标受理给出条件
Object.assign(s, ((s,p)=>({acceptGoal:s.active,readyCount:Number(s.configured)+Number(p.sensor==='yes')}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"mapOdom":0.5,"odomBase":1,"age":0.2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先检查坐标链
Object.assign(s, ((s,p)=>({chain:['map','odom','base_link','laser'],laserOffset:.2}))(s, p));
// 复合相同时间的变换
Object.assign(s, ((s,p)=>({laserMap:p.mapOdom+p.odomBase+s.laserOffset}))(s, p));
// 把观测从laser变到map
Object.assign(s, ((s,p)=>({endpointMap:s.laserMap+2}))(s, p));
// 用教学阈值检查时效
Object.assign(s, ((s,p)=>({fresh:p.age<=.3,usable:p.age<=.3,ageSeconds:p.age}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"cell":4,"resolution":0.1,"origin":-1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 读取地图元数据
Object.assign(s, ((s,p)=>({column:p.cell,resolution:p.resolution,origin:p.origin}))(s, p));
// 将栅格中心换到世界坐标
Object.assign(s, ((s,p)=>({world:p.origin+(p.cell+.5)*p.resolution}))(s, p));
// 区分先验位姿和定位结果
Object.assign(s, ((s,p)=>({initialPose:.2,correction:-.1,localizedPose:.1}))(s, p));
// 写出目标相对位移
Object.assign(s, ((s,p)=>({relativeGoal:s.world-s.localizedPose,cellRoundTrip:Math.floor((s.world-p.origin)/p.resolution)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"radius":0.2,"inflation":0.2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 给出通道净宽
Object.assign(s, ((s,p)=>({width:.9,diameter:2*p.radius}))(s, p));
// 先检查几何可通过性
Object.assign(s, ((s,p)=>({physicalMargin:s.width-2*p.radius,geometricPass:s.width>2*p.radius}))(s, p));
// 加入规划缓冲要求
Object.assign(s, ((s,p)=>({preferredWidth:2*(p.radius+p.inflation),bufferMargin:s.width-2*(p.radius+p.inflation)}))(s, p));
// 区分碰撞与偏好
Object.assign(s, ((s,p)=>({bufferPass:s.bufferMargin>0,geometricPass:s.geometricPass}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"penalty":2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 定义同一地图上的两条候选路径
Object.assign(s, ((s,p)=>({lengths:[3,4],proximity:[2,.2]}))(s, p));
// 把路径成本写明
Object.assign(s, ((s,p)=>({costs:s.lengths.map((x,i)=>x+p.penalty*s.proximity[i])}))(s, p));
// 按同一个目标选择
Object.assign(s, ((s,p)=>({choice:s.costs[0]<=s.costs[1]?0:1}))(s, p));
// 保存选择依据
Object.assign(s, ((s,p)=>({selectedLength:s.lengths[s.choice],selectedCost:s.costs[s.choice]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"lookahead":1,"speed":0.5,"y":0.2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 把前视目标放到机体系
Object.assign(s, ((s,p)=>({target:[Math.sqrt(p.lookahead*p.lookahead-p.y*p.y),p.y]}))(s, p));
// 由圆弧几何求曲率
Object.assign(s, ((s,p)=>({curvature:2*p.y/(p.lookahead*p.lookahead)}))(s, p));
// 速度乘曲率得到角速度
Object.assign(s, ((s,p)=>({omega:p.speed*s.curvature}))(s, p));
// 检查离散控制周期
Object.assign(s, ((s,p)=>({headingStep:s.omega*.05,travelStep:p.speed*.05}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"failures":1,"budget":2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先初始化一个有界恢复流程
Object.assign(s, ((s,p)=>({events:[],attempts:0}))(s, p));
// 执行明确的有限规则
Object.assign(s, ((s,p)=>{const events=[];let success=false,recoveries=0;for(let attempt=0;attempt<=p.budget;attempt++){events.push('plan '+attempt);if(attempt>=p.failures){events.push('follow');success=true;break;}if(attempt<p.budget){recoveries++;events.push('recover');}}return {events,success,recoveries,attempts:Math.min(p.failures+1,p.budget+1)};})(s, p));
// 区分运行、成功和失败
Object.assign(s, ((s,p)=>({status:s.success?'SUCCESS':'FAILURE'}))(s, p));
// 记录结束原因
Object.assign(s, ((s,p)=>({stoppedBy:s.success?'路径与跟踪分支成功':'恢复预算耗尽'}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={wilson:(success,n)=>{const z=1.96,p=success/n,d=1+z*z/n,m=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [m-h,m+h];}};
const p={"successes":8,"contacts":0,"timeouts":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 在同一场景集上比较
Object.assign(s, ((s,p)=>({episodes:10,successes:p.successes,contacts:p.contacts,timeouts:p.timeouts}))(s, p));
// 计算成功率和区间
Object.assign(s, ((s,p)=>({rate:s.successes/s.episodes,interval:H.wilson(s.successes,s.episodes)}))(s, p));
// 按预先写下的门槛核对
Object.assign(s, ((s,p)=>({pass:s.rate>=.8&&s.contacts===0&&s.timeouts<=1}))(s, p));
// 为下一步保留证据类型
Object.assign(s, ((s,p)=>({evidence:'人工教学数据',targetEnvironment:'ROS 2 Jazzy + Gazebo Harmonic'}))(s, p));
console.log(JSON.stringify(s,null,2));
